"""Bounded read-only schema probe through the existing loopback-only CF pattern."""
from pathlib import Path
import json
import os
import secrets
import shutil
import subprocess
import tempfile

root = Path('/var/www/business.roadrunners.run')
work = Path(tempfile.mkdtemp(prefix='business-home-hash-', dir=root / '_codex'))
os.chmod(work, 0o755)
token = secrets.token_hex(32)
body = '<cfsetting showdebugoutput="false" requesttimeout="30"/><cfcontent type="application/json" reset="true"/><cfscript>\nreport={cases=[]};tests=deserializeJSON(toString(binaryDecode("","base64")));opts={datasource="runnerhub",timeout=6};\nfor(test in tests){\n started=getTickCount();item={name=test.name,days=test.days,loaded=false};\n try {transaction {queryExecute("SET TRANSACTION READ ONLY",{},opts);queryExecute("SET LOCAL statement_timeout=\'5s\'",{},opts);\n q=queryExecute(test.sql,{days={value=test.days,cfsqltype="cf_sql_integer"}},opts);item.loaded=true;\n if(test.plan){item.plan=deserializeJSON(q["QUERY PLAN"][1]);}else{item.metrics=queryGetRow(q,1);}\n }}catch(any e){item.error_type=e.type;if(structKeyExists(e,"sqlState"))item.sqlstate=e.sqlState;}\n item.elapsed_ms=getTickCount()-started;arrayAppend(report.cases,item);\n}\nwriteOutput(serializeJSON(report));</cfscript>'
try:
    (work / '.htaccess').write_text('Require local\n')
    (work / 'Application.cfc').write_text(
        'component {this.name="' + work.name + '";this.datasource="runnerhub";'
        'boolean function onRequestStart(string target){'
        'if(!listFind("127.0.0.1,::1",cgi.remote_addr)||cgi.request_method!="POST"||'
        'compare(form.key ?: "","' + token + '")!=0){cfheader(statuscode=404);abort;}'
        'return true;}}')
    (work / 'run.cfm').write_text(body)
    for path in work.iterdir():
        os.chmod(path, 0o644)
    result = subprocess.run([
        'curl', '-sS', '--max-time', '28', '--resolve',
        'business.roadrunners.run:443:127.0.0.1', '-X', 'POST',
        '--data-urlencode', 'key=' + token,
        'https://business.roadrunners.run/_codex/' + work.name + '/run.cfm',
    ], capture_output=True, text=True, timeout=31)
    if result.returncode:
        raise RuntimeError('Schema request failed; transport output withheld')
    try:
        report = json.loads(result.stdout)
    except ValueError:
        raise RuntimeError('Schema request returned non-JSON; response withheld')
    report.update(read_only=True, runtime_files_changed=False, query_sha256='08758e0c80ea1fa90ab6c6eafe026a62e39e5b04dfe3cb450cf6d9431c64802f')
finally:
    shutil.rmtree(work)
print(json.dumps(report, indent=2))
